		if limited.CompareAndSwap(false, true) {
			w.Header().Set("Retry-After", "1")
			w.WriteHeader(429)
			return
		}
		var ids []string
		for i := 0; i < nCust; i++ {
			ids = append(ids, fmt.Sprintf("cus_%04d", i))
		}
