				}
			}
			ids = append(ids, fmt.Sprintf("sub_%04d", i))
			status = append(status, st)
		}
		page(w, r, ids, func(i int) string {
			return fmt.Sprintf(`{"id":%q,"object":"subscription","customer":"cus_0000","status":%q,"created":%d}`, ids[i], status[i], 1700000000+i)
		})
	}))
